(function(){'use strict';
const source="data:image/png;base64,";
const wordSource="data:image/png;base64,";
class ArcherApertureOrb{
 constructor(host){this.host=host;this.state='idle';this.amplitude=0;this.energy=0;this.phase=0;this.reference=false;this.paused=false;this.dead=false;this.last=0;this.lastAmplitude=0;this.handlers=[];
 this.canvas=document.createElement('canvas');this.canvas.className='archer-approved';this.canvas.setAttribute('role','img');this.canvas.setAttribute('aria-label','ARCHER aperture — idle');host.replaceChildren(this.canvas);this.ctx=this.canvas.getContext('2d');this.wordImage=new Image();this.wordImage.src=wordSource;this.image=new Image();this.image.src=source;this.image.onload=()=>this.resize();this.image.onerror=()=>{host.textContent='Orb artwork could not load. Check web/assets/approved.png.';};this.motion=matchMedia('(prefers-reduced-motion: reduce)');this.observer=new ResizeObserver(()=>this.resize());this.observer.observe(host);this.bindClient();this.tick=this.tick.bind(this);this.raf=requestAnimationFrame(this.tick);}
 resize(){const w=Math.max(1,this.host.clientWidth),d=Math.min(devicePixelRatio||1,2);this.canvas.width=Math.round(w*d);this.canvas.height=Math.round(w*1145/1374*d);}
 bindClient(client=window.ArcherClient){if(!client||this.client===client)return;this.client=client;const on=(n,h)=>{const off=client.on(n,h);if(typeof off==='function')this.handlers.push(off);};on('state',e=>this.setState(typeof e==='string'?e:e?.state));on('amplitude',e=>this.setAmplitude(typeof e==='number'?e:e?.value));on('halt',()=>this.setState('halted'));on('wakeWord',()=>this.setState('listening'));}
 setState(s){if(!['idle','listening','processing','speaking','error','halted'].includes(s))return;this.state=s;this.canvas.setAttribute('aria-label','ARCHER aperture — '+s);if(s!=='speaking'){this.amplitude=0;this.energy=0;}}
 setAmplitude(a){a=Number(a);this.amplitude=Number.isFinite(a)?Math.max(0,Math.min(1,a)):0;this.lastAmplitude=performance.now();}
 setReference(v){this.reference=!!v;}
 setPaused(v){this.paused=!!v;}
 // Build independent render surfaces once. Never rotate the wordmark with the aperture.
 prepareLayers(){
 const make=()=>{const x=document.createElement('canvas');x.width=1374;x.height=1145;return x;};
 const art=make(),ac=art.getContext('2d');ac.drawImage(this.image,0,0,1374,1145);
 const original=ac.getImageData(0,0,1374,1145),data=ac.getImageData(0,0,1374,1145),src=original.data,d=data.data;
 // Reconstruct the narrow lettering band from another angular sector of the same aperture.
 // This avoids retaining a second, rotating copy of ARCHER.
 for(let y=510;y<510;y++)for(let x=394;x<903;x++){
   const dx=x-640,dy=y-555,r=Math.hypot(dx,dy),o=(y*1374+x)*4;
   if(r<116){d[o]=3;d[o+1]=24;d[o+2]=39;continue;}
   const a=Math.atan2(dy,dx)+(dy<0?-1:1)*Math.PI/2;
   const sx=Math.round(640+r*Math.cos(a)),sy=Math.round(555+r*Math.sin(a)),q=(sy*1374+sx)*4;
   for(let k=0;k<3;k++)d[o+k]=src[q+k];
 }
 ac.putImageData(data,0,0);this.layers=[];
 for(const [inner,outer,speed] of [[0,318,.20],[329,344,-.13],[350,404,.29],[417,448,-.18],[456,486,.12]]){
   const layer=make(),lc=layer.getContext('2d');lc.save();lc.beginPath();lc.arc(640,555,outer,0,Math.PI*2);if(inner)lc.arc(640,555,inner,0,Math.PI*2,true);lc.clip('evenodd');lc.drawImage(art,0,0);lc.restore();this.layers.push({image:layer,speed});
 }
 const word=make(),wc=word.getContext('2d');wc.drawImage(this.wordImage,0,0,1374,1145);const ws=wc.getImageData(0,0,1374,1145).data;wc.clearRect(0,0,1374,1145);const letters=wc.createImageData(1374,1145),ld=letters.data;
 for(let y=540;y<592;y++)for(let x=427;x<875;x++){
   const o=(y*1374+x)*4;
   const alpha=Math.max(0,Math.min(1,(Math.min(ws[o+1],ws[o+2])-130)/45));
   const v=(y-540)/52,mid=Math.sin(v*Math.PI);
   ld[o]=125+mid*110;ld[o+1]=245-mid*32;ld[o+2]=248;ld[o+3]=alpha*255;
 }
 wc.putImageData(letters,0,0);this.wordmark=word;
 }
 draw(){
 if(!this.image.naturalWidth||!this.wordImage.naturalWidth)return;if(!this.layers)this.prepareLayers();
 const c=this.ctx;c.setTransform(this.canvas.width/1374,0,0,this.canvas.height/1145,0,0);c.clearRect(0,0,1374,1145);
 const t=this.reference?0:this.phase;
 for(const layer of this.layers){c.save();c.translate(640,555);c.rotate(t*layer.speed);c.translate(-640,-555);c.drawImage(layer.image,0,0);c.restore();}
 // The spaces between the rings and all corners remain genuinely transparent.
 c.save();c.strokeStyle='#71e8ff';c.shadowColor='#3be0ff';c.shadowBlur=7;c.lineWidth=1.5;
 for(const r of [322,410,452]){c.beginPath();c.arc(640,555,r,0,Math.PI*2);c.stroke();}
 const a=this.energy;c.lineWidth=2;
 for(let i=0;i<100;i++){const p=i*Math.PI/50-t*.14,r=407,len=2+a*(8+15*Math.abs(Math.sin(i*.71+t*6)));c.beginPath();c.moveTo(640+Math.cos(p)*r,555+Math.sin(p)*r);c.lineTo(640+Math.cos(p)*(r+len),555+Math.sin(p)*(r+len));c.stroke();}
 c.restore();c.save();c.shadowColor='#98b5ff';c.shadowBlur=10;c.drawImage(this.wordmark,0,0);c.restore();
 }

 tick(now){if(this.dead)return;const dt=Math.min(.05,(now-this.last)/1000||0);this.last=now;const stop=this.paused||this.reference||this.motion.matches||['halted','error'].includes(this.state);if(!stop){this.phase+=dt*({idle:.65,listening:1,processing:2.1,speaking:1.4}[this.state]||0);let target=this.state==='speaking'?(now-this.lastAmplitude<400?this.amplitude:0):this.state==='listening'?.14+.1*Math.sin(this.phase*2):this.state==='processing'?.25+.15*Math.sin(this.phase*5):.025;this.energy+=(target-this.energy)*(1-Math.exp(-dt*12));}this.draw();this.raf=requestAnimationFrame(this.tick);}
 destroy(){this.dead=true;cancelAnimationFrame(this.raf);this.observer.disconnect();this.handlers.forEach(f=>f());this.host.replaceChildren();}
}
window.ArcherApertureOrb=ArcherApertureOrb;function mount(){const h=document.querySelector('[data-archer-orb],#orb-container,#orb,.orb-container');if(h&&h.tagName!=='CANVAS')window.ArcherOrb=new ArcherApertureOrb(h);}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',mount,{once:true});else mount();
})();
